INSERT INTO public.assessment_questions (framework, section_id, section_name, subsection, question_number, question, why_matters, regulatory_ref, risk, evidence_req, remediation, uid) VALUES
('popia', 3, 'Special Personal Information', 'Identification and Processing', 1, 'Has the organisation identified all categories of special personal information it processes?', 'Section 26 special personal information requires organisations to identify and handle special categories with additional safeguards. Unidentified special personal information is a compliance risk.', 'POPIA Section 26 special personal information; Information Regulator Guidance on Special PI', 'Critical', 'Data inventory showing special PI categories; special PI register; risk assessment for special PI; processing records for special PI.', 'Conduct comprehensive data inventory to identify all special personal information categories. Maintain special PI register. Implement enhanced safeguards.', 'P3_SPI_1'),
('popia', 3, 'Special Personal Information', 'Identification and Processing', 2, 'Does the organisation have documented procedures for processing criminal behaviour information?', 'Criminal behaviour is a special category that requires specific authorisation under Section 27 unless the data subject consents or it''s for legal proceedings.', 'POPIA Section 27 criminal behaviour; Information Regulator Guidance on Special PI', 'Critical', 'Authorisation documentation; consent records; legal proceeding documentation; processing procedures for criminal data.', 'Obtain prior authorisation from Information Regulator for criminal data processing unless consented or for legal proceedings. Document all authorisations.', 'P3_SPI_2'),
('popia', 3, 'Special Personal Information', 'Identification and Processing', 3, 'Are race, ethnic origin, and political persuasion data being processed for B-BBEE verification purposes?', 'B-BBEE verification requires processing of race and ethnic origin data. This is permitted under Section 27 but requires specific authorisation.', 'POPIA Section 27 B-BBEE verification; B-BBEE Act requirements; Information Regulator Guidance', 'High', 'B-BBEE verification authorisation; consent records; B-BBEE Act compliance documentation; processing procedures for demographic data.', 'Obtain authorisation for B-BBEE verification processing. Document B-BBEE Act compliance. Implement consent mechanisms where possible.', 'P3_SPI_3'),
('popia', 3, 'Special Personal Information', 'Trade Union Membership', 4, 'Is trade union membership information processed only where necessary and with appropriate safeguards?', 'Trade union membership is a special category requiring appropriate safeguards under Section 26.', 'POPIA Section 26 special personal information; Information Regulator Guidance on Special PI', 'Medium', 'Trade union data processing procedures; necessity assessments; consent records; access controls for union data.', 'Assess necessity of trade union membership information. Implement appropriate safeguards. Obtain consent where possible.', 'P3_SPI_4'),
('popia', 3, 'Special Personal Information', 'Political Persuasion', 5, 'Are political persuasion data processed only for legitimate purposes and with appropriate safeguards?', 'Political persuasion is a special category requiring appropriate safeguards under Section 26.', 'POPIA Section 26 special personal information; Information Regulator Guidance on Special PI', 'Medium', 'Political data processing procedures; legitimacy assessments; consent records; access controls.', 'Assess legitimacy of political data processing. Implement appropriate safeguards. Obtain consent where possible.', 'P3_SPI_5'),
('popia', 3, 'Special Personal Information', 'Religious and Philosophical Beliefs', 6, 'Are religious and philosophical beliefs processed only where necessary and with appropriate safeguards?', 'Religious and philosophical beliefs are a special category requiring appropriate safeguards under Section 26.', 'POPIA Section 26 special personal information; Information Regulator Guidance on Special PI', 'Medium', 'Religious data processing procedures; necessity assessments; consent records; access controls.', 'Assess necessity of religious data processing. Implement appropriate safeguards. Obtain consent where possible.', 'P3_SPI_6'),
('popia', 3, 'Special Personal Information', 'Health Information', 7, 'Does the organisation have appropriate safeguards for processing health information?', 'Health information is a special category requiring appropriate safeguards under Section 26.', 'POPIA Section 26 special personal information; Information Regulator Guidance on Special PI; National Health Act requirements', 'High', 'Health data processing procedures; consent procedures; access controls; medical records management.', 'Implement enhanced safeguards for health information. Obtain informed consent where required. Ensure compliance with health-specific legislation.', 'P3_SPI_7'),
('popia', 3, 'Special Personal Information', 'Biometric Data', 8, 'Are biometric data processed only with consent and appropriate security measures?', 'Biometric data is highly sensitive and requires explicit consent and appropriate security measures under Section 26.', 'POPIA Section 26 special personal information; Information Regulator Guidance on Special PI; POPIA Regulations on biometric data', 'Critical', 'Biometric consent records; security assessment for biometric systems; storage encryption; access controls for biometric data.', 'Obtain explicit consent for biometric processing. Implement appropriate security measures including encryption and access controls.', 'P3_SPI_8'),
('popia', 3, 'Special Personal Information', 'Prior Authorisation', 9, 'Has the organisation obtained prior authorisation for processing special personal information where required?', 'Section 27 requires prior authorisation from the Information Regulator for certain special personal information processing activities.', 'POPIA Section 27 prior authorisation; Information Regulator application procedures; Section 27(1) exceptions', 'Critical', 'Authorisation certificates from Information Regulator; application documentation; evidence of meeting exception criteria; renewal records.', 'Apply for prior authorisation from Information Regulator where required. Maintain authorisation certificates and renewal schedules.', 'P3_SPI_9'),
('popia', 3, 'Special Personal Information', 'Risk Assessment', 10, 'Are risk assessments conducted for all special personal information processing activities?', 'Section 26 requires organisations to assess risks associated with special personal information and implement appropriate safeguards.', 'POPIA Section 26 risk assessment; ISO 27701 cl.6.1.3 risk assessment; DPIA methodology', 'High', 'Risk assessment records; safeguard implementation documentation; risk register for special PI; evidence of risk mitigation.', 'Conduct risk assessments for all special personal information processing. Implement appropriate safeguards based on risk level. Maintain risk register.', 'P3_SPI_10');